annualTextHTML('CRDO annual NOPAT = EBIT × (1 − tax rate). First-year FCFF prorates annual NOPAT minus entered investment by remaining revenue and days, then subtracts remaining capacity deposits and adds recoveries. Discounting uses the remaining fiscal stub, then annual WACC. Every liquidity checkpoint must meet the selected floor; no financing is invented.')}</p>`:d.ticker==='MRVL'?`<p class="micro">${annualTextHTML(MRVL_MESSAGES.note[0])}</p>`:d.ticker==='FN'?`<p class="micro">${annualTextHTML('FN FCFF subtracts total funded investment: the pre-reserve input plus required-cash change. Annual WACCs compound; terminal investment already includes cash. Operating EV stays signed; nonpositive allocation pools produce zero ordinary value and a separately retained shortfall.')}</p>`:'<p class="micro" data-i18n="annual.copy.ccc66499e2c0">Annual tax = max(0, EBIT) × tax rate. FCFF = NOPAT − direct investment. Discount factors compound each annual WACC. Terminal value = terminal NOPAT × (1 − g / ROIC) / (WACC − g). Signed operating and common-equity results are retained.</p>'}</details>`;
  if(region==='summary')return markup.split('<!-- annual-analysis -->')[0];
  if(region==='analysis')return markup.split('<!-- annual-analysis -->')[1]||'';
  return markup;
 }catch(error){return region==='analysis'?'<div id="research-simulation-root"></div>':`<div class="error" role="status"><h2 data-i18n="annual.copy.b4738b0f4ca1">Check the edited annual inputs</h2><p>${annualTextHTML(error.message)}</p><p data-i18n="annual.copy.6e4c2cadb004">Results are withheld until the inputs are valid. Your draft is retained.</p></div>`;}
}

export function researchEditorHTML(c,d){
 if(!d||!Array.isArray(d.annual)||!d.terminal)return '<p class="error" data-i18n="annual.copy.76c4f512e083">This saved draft cannot be edited safely. Export it or explicitly load the reviewed case.</p>';
 const fields=[['revenue',`Revenue · ${d.currency}m`,1],['margin','EBIT margin %',100],['taxRate','Operating tax %',100],['reinvestment',`${d.operatingCashFunding?'Investment before cash-reserve change':'Net investment'} · ${d.currency}m`,1],['wacc','WACC %',100]];
 const tfields=[['growth','Stable revenue growth %'],['margin','Terminal EBIT margin %'],['taxRate','Terminal tax %'],['roic','Terminal ROIC %'],['wacc','Terminal WACC %']];
