 const load=preset?'<button class="quiet" data-research-action="load-current-capital" data-i18n="annual.copy.7ef4f524ecd7">Use researched capital scenario</button><p class="micro" data-i18n="annual.copy.f35b8308e974">Loads dated capital and matching timing only. Annual operating edits and notes stay; Undo last load restores the previous case.</p>':'';
 if(!scenario||typeof scenario!=='object'||Array.isArray(scenario))return `<p class="research-warning" data-i18n="annual.copy.c2a24922fb18">The saved capital scenario needs correction. Its original data is retained for export.</p>${load}`;
