 const pricing=scenario.optionPricing;
 const optionControls=pricing?`<h4 data-i18n="annual.copy.b3621a17092f">Option-inclusive claim approximation</h4><div class="research-field-grid">${[['volatility','Volatility assumption',100],['creditSpread','Credit spread assumption',100],['riskFreeRate','Risk-free rate proxy',100],['dividendYield','Dividend yield assumption',100],['warrantShares','Existing customer warrant shares · millions',1]].map(([key,label,scale])=>`<label>${annualTextHTML(label)}${scale===100?' · %':''}${input('optionPricing.'+key,pricing[key],label,{group:'current-capital',scale,min:0})}</label>`).join('')}</div><p class="micro" data-i18n="annual.copy.8ce9fd8e6fc6">Note and customer-warrant claims are recalculated with operating value in every valuation and simulation draw. Historical 80% volatility is a selected assumption, not current observed volatility. Do not add conversion shares, exercise shares or proceeds again.</p><details><summary data-i18n="annual.copy.dc135bf053af">Contract terms held fixed</summary>${rationaleHTML(Object.fromEntries(Object.entries(pricing).filter(([key])=>!['volatility','creditSpread','riskFreeRate','dividendYield','warrantShares'].includes(key))))}</details>`:'';
 const award=scenario.existingAwardSensitivity;
