  const scale=field.scale??(field.max===1?100:1),label=field.label+(scale===100?' · %':field.unit?' · '+field.unit:'');
  return `<label>${annualTextHTML(label)}${input(field.key,value,label,{group:'bridge',scale,min:field.min==null?undefined:field.min*scale,max:field.max==null?undefined:field.max*scale}).replace('<input ',d.ticker==='KEYS'?'<input aria-describedby="keys-claims-help" ':d.ticker==='SNPS'?'<input aria-describedby="snps-claims-help" ':d.openingStub?'<input aria-describedby="cdns-claims-help" ':'<input ')}${value===null?'<small data-i18n="annual.copy.054c3155e34e">Required amount is unknown; blank does not mean zero.</small>':''}</label>`;
